@@ -40,4 +40,36 @@ export async function openDb(): Promise<PGlite> {
     ANALYZE;
   `);
+
+  // Materialized view: pre-computed top-customers ranking.
+  // The unique index on customer_id is required for CONCURRENT refresh.
+  await db.exec(`
+    CREATE MATERIALIZED VIEW top_customers_mv AS
+      SELECT c.id AS customer_id,
+             c.name,
+             sum(o.amount_cents)::int AS revenue_cents,
+             count(*)::int            AS orders
+      FROM orders o
+      JOIN customers c ON c.id = o.customer_id
+      WHERE o.status = 'paid'
+        AND o.created_at > now() - interval '30 days'
+      GROUP BY c.id, c.name;
+
+    CREATE UNIQUE INDEX top_customers_mv_pk ON top_customers_mv (customer_id);
+  `);
+
   return db;
 }
+
+// Refresh the materialized view concurrently (non-blocking reads during refresh).
+// Returns a stop() function that cancels the interval — call it in tests / on
+// server shutdown to avoid open handles.
+export function startRefresher(db: PGlite, intervalMs = 5_000): () => void {
+  const id = setInterval(() => {
+    db.exec("REFRESH MATERIALIZED VIEW CONCURRENTLY top_customers_mv").catch(() => {
+      // Swallow errors — a missed refresh is not fatal; the next tick will retry.
+    });
+  }, intervalMs);
+  // Allow Node to exit even if the interval is still live (belt-and-braces).
+  if (typeof id === "object" && "unref" in id) (id as NodeJS.Timeout).unref();
+  return () => clearInterval(id);
+}
